import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register } from 'claude-code'

import type { Detail, FileDiff, GitHub, Graph, GraphRow, Naming, PullRequest, Scope, Search, WorkTree } from '../types'
import {
  COLORS,
  LOG_FORMAT,
  ROW,
  ago,
  clip,
  closeOver,
  pills,
  shortAgo,
  shortAuthor,
  shortSubject,
  filterRows,
  layout,
  parseLog,
  parseNumstat,
  parsePrs,
  parseRuns,
  parseStashes,
  parseStatus,
  parseTracks,
  readSearch,
  rowCells,
  rowSvg,
  scopeRange,
  splitPatch,
} from './layout'

const PANE = 'git-graph'
const PAGE = 200
const GITHUB_TTL = 120000

const graph = atom({ plugin: 'git-graph', key: 'graph' } as const, null)
const selected = atom({ plugin: 'git-graph', key: 'selected' } as const, null)
const detail = atom({ plugin: 'git-graph', key: 'detail' } as const, null)
const diff = atom({ plugin: 'git-graph', key: 'diff' } as const, null)
const limit = atom({ plugin: 'git-graph', key: 'limit' } as const, PAGE)
const scope = atom({ plugin: 'git-graph', key: 'scope' } as const, 'all')
const query = atom({ plugin: 'git-graph', key: 'query' } as const, '')
const search = atom({ plugin: 'git-graph', key: 'search' } as const, null)
const compareBase = atom({ plugin: 'git-graph', key: 'compareBase' } as const, null)
const claude = atom({ plugin: 'git-graph', key: 'claude' } as const, [])
const github = atom({ plugin: 'git-graph', key: 'github' } as const, null)
const isStashOpen = atom({ plugin: 'git-graph', key: 'isStashOpen' } as const, false)
const naming = atom({ plugin: 'git-graph', key: 'naming' } as const, null)
/** The first commit the desktop pane shows: it draws one page of commits at a time. */
const offset = atom({ plugin: 'git-graph', key: 'offset' } as const, 0)
const isHelpOpen = atom({ plugin: 'git-graph', key: 'isHelpOpen' } as const, false)
const isMoreOpen = atom({ plugin: 'git-graph', key: 'isMoreOpen' } as const, false)

/** The desktop pane goes blank past this many commit rows. */
const DESKTOP_PAGE = 60


const KEYS = {
  size: 'git-graph:size',
  scope: 'git-graph:scope',
  stashes: 'git-graph:stashes-open',
  claude: (repo: string) => `git-graph:claude:${repo}`,
}

/** Secondary text: light enough to read on the desktop's dark panes, where `dimColor` is too faint. */
const MUTED = '#A9B1BD'

const REF_STYLE = {
  head: { bg: '#4FA3F7', fg: '#0B2440' },
  branch: { bg: '#2BB3A3', fg: '#06302B' },
  remote: { bg: '#B07CE8', fg: '#2A1145' },
  tag: { bg: '#F5B400', fg: '#3D2A00' },
} as const

const CHECK_GLYPH = { pass: '✓', fail: '✗', pending: '●', none: '' } as const
const CHECK_COLOR = { pass: 'success', fail: 'error', pending: 'warning', none: 'inactive' } as const

// ---------------------------------------------------------------- git and gh (read-only)

/** Read-only git: never takes the index lock, never runs repo hooks. */
async function git($: EngineInterface, args: string[], cwd?: string) {
  return $.process.run(['git', '--no-optional-locks', '-c', 'core.quotepath=off', ...args], {
    cwd,
    timeoutMs: 20000,
  })
}

async function repoRoot($: EngineInterface): Promise<string | null> {
  const top = await git($, ['rev-parse', '--show-toplevel'])
  return top.exitCode === 0 ? top.stdout.trim() : null
}

async function headOf($: EngineInterface, root?: string): Promise<string | null> {
  const head = await git($, ['rev-parse', '--verify', '-q', 'HEAD'], root)
  return head.exitCode === 0 ? head.stdout.trim() : null
}

/** Changes whenever a ref moves: a commit, a fetch, a checkout, a new tag. */
async function refSignature($: EngineInterface, root: string): Promise<string> {
  return (await git($, ['show-ref', '--head'], root)).stdout
}

async function workTree($: EngineInterface, root?: string): Promise<WorkTree | null> {
  const status = await git($, ['status', '--porcelain=v2', '--branch', '--untracked-files=normal'], root)
  return status.exitCode === 0 ? parseStatus(status.stdout) : null
}

function narrowing(search: Search | null): { revs: string[]; tail: string[] } {
  if (!search) return { revs: [], tail: [] }
  if (search.mode === 'path') return { revs: [], tail: ['--', search.q] }
  if (search.mode === 'hash') return { revs: [], tail: [] }
  return { revs: ['-i', `--grep=${search.q}`, `--author=${search.q}`], tail: [] }
}

async function loadGraph(
  $: EngineInterface,
  root: string,
  opts: { max: number; scope: string; search: Search | null },
): Promise<Graph> {
  const { search } = opts
  let range = scopeRange(opts.scope)
  if (search?.mode === 'hash') {
    const found = await git($, ['rev-parse', '--verify', '-q', `${search.q}^{commit}`], root)
    if (found.exitCode !== 0) {
      return empty(root, `No commit matches ${search.q}.`)
    }
    range = [found.stdout.trim()]
  }
  const { revs, tail } = narrowing(search)

  const [log, count, remoteList, head, refs, stashList, status] = await Promise.all([
    git($, ['log', '--topo-order', `-n${opts.max}`, `--format=${LOG_FORMAT}`, ...revs, ...range, ...tail], root),
    git($, ['rev-list', '--count', ...revs, ...range, ...tail], root),
    git($, ['remote'], root),
    headOf($, root),
    git($, ['for-each-ref', '--format=%(refname:short)%09%(upstream:short)%09%(upstream:track)', 'refs/heads'], root),
    git($, ['stash', 'list', '--format=%H%x1f%gd%x1f%s%x1f%at'], root),
    workTree($, root),
  ])
  const tagList = await git($, ['tag', '--sort=-creatordate'], root)

  if (log.exitCode !== 0) {
    const isEmpty = /does not have any commits|unknown revision|bad default revision/.test(log.stderr)
    return empty(root, isEmpty ? 'No commits yet.' : log.stderr.trim() || 'git log failed.')
  }

  const remotes = lines(remoteList.stdout)
  const commits = parseLog(log.stdout)
  const { rows, width } = layout(search ? closeOver(commits) : commits, remotes)
  const tracks = parseTracks(refs.stdout)

  return {
    repo: root,
    total: Number(count.stdout.trim()) || rows.length,
    rows,
    width,
    head,
    tracks,
    branches: lines(refs.stdout).map(line => line.split('\t')[0] ?? '').filter(Boolean),
    tags: lines(tagList.stdout).slice(0, 50),
    work: status,
    stashes: parseStashes(stashList.stdout),
  }
}

function empty(repo: string, error: string): Graph {
  return { repo, total: 0, rows: [], width: 1, head: null, tracks: {}, branches: [], tags: [], work: null, stashes: [], error }
}

function lines(text: string): string[] {
  return text
    .split('\n')
    .map(line => line.trim())
    .filter(Boolean)
}

/** Pull requests and CI runs through the `gh` CLI, read-only; any failure is kept as `error`. */
async function loadGitHub($: EngineInterface, root: string, now: number): Promise<GitHub> {
  const run = (args: string[]) => $.process.run(['gh', ...args], { cwd: root, timeoutMs: 25000 })
  try {
    const [prs, runs] = await Promise.all([
      run(['pr', 'list', '--state', 'all', '--limit', '100', '--json', 'number,state,isDraft,headRefName,url,statusCheckRollup']),
      run(['run', 'list', '--limit', '60', '--json', 'headSha,status,conclusion']),
    ])
    if (prs.exitCode !== 0) {
      return { prs: {}, runs: {}, fetchedAt: now, error: prs.stderr.trim().split('\n')[0] || 'gh failed' }
    }
    return {
      prs: parsePrs(prs.stdout),
      runs: runs.exitCode === 0 ? parseRuns(runs.stdout) : {},
      fetchedAt: now,
    }
  } catch (error) {
    return { prs: {}, runs: {}, fetchedAt: now, error: String(error) }
  }
}

const WORKTREE = 'WORKTREE'

async function loadDetail(
  $: EngineInterface,
  root: string | undefined,
  hash: string,
  base: string | null,
): Promise<Detail> {
  if (hash === WORKTREE) {
    const stat = await git($, ['diff', '--numstat', '-M', 'HEAD'], root)
    return {
      kind: 'worktree',
      hash: WORKTREE,
      short: 'working tree',
      author: '',
      email: '',
      time: 0,
      subject: 'Uncommitted changes',
      body: '',
      parents: [],
      files: parseNumstat(stat.stdout),
    }
  }

  const [meta, stat] = await Promise.all([
    git($, ['show', '-s', '--format=%H%x1f%an%x1f%ae%x1f%at%x1f%P%x1f%s%x1f%b', hash], root),
    base
      ? git($, ['diff', '--numstat', '-M', base, hash], root)
      : git($, ['show', '--numstat', '--format=', '-M', '--diff-merges=first-parent', hash], root),
  ])
  const [full, author, email, time, parents, subject, body] = meta.stdout.split('\x1f')
  const id = (full ?? hash).trim()
  return {
    kind: base ? 'compare' : 'commit',
    hash: id,
    short: id.slice(0, 7),
    base: base ?? undefined,
    author: author ?? '',
    email: email ?? '',
    time: Number(time) || 0,
    parents: (parents ?? '').split(' ').filter(Boolean),
    subject: base ? `${base.slice(0, 7)}..${id.slice(0, 7)}` : (subject ?? ''),
    body: base ? `Changes from ${base.slice(0, 7)} to ${id.slice(0, 7)}` : (body ?? '').trim(),
    files: parseNumstat(stat.stdout),
  }
}

async function loadPatch($: EngineInterface, root: string | undefined, det: Detail): Promise<FileDiff[]> {
  const args =
    det.kind === 'worktree'
      ? ['diff', '-M', 'HEAD']
      : det.kind === 'compare' && det.base
        ? ['diff', '-M', det.base, det.hash]
        : ['show', '--format=', '--patch', '-M', '--diff-merges=first-parent', det.hash]
  const patch = await git($, args, root)
  return splitPatch(patch.stdout, 40000)
}

// ---------------------------------------------------------------- loading

let lastSignature = ''
let isLoading = false

async function load($: EngineInterface): Promise<void> {
  if (isLoading) return
  isLoading = true
  try {
    const root = await repoRoot($)
    if (root === null) {
      const error: Graph = {
        repo: '',
        total: 0,
        rows: [],
        width: 1,
        head: null,
        tracks: {},
        branches: [],
        tags: [],
        work: null,
        stashes: [],
        error: 'This folder is not a git repository.',
      }
      await update($, graph, () => error)
      return
    }
    const [max, which, narrowed] = await Promise.all([read($, limit), read($, scope), read($, search)])
    const [next, sig] = await Promise.all([
      loadGraph($, root, { max, scope: which, search: narrowed }),
      refSignature($, root),
    ])
    lastSignature = sig
    await update($, graph, () => next)
    showStatus($, next)
    $.ui.invalidate('ui.render')
    await restoreClaude($, root)
    void refreshGitHub($, root, false)
  } finally {
    isLoading = false
  }
}

async function isOpen($: EngineInterface): Promise<boolean> {
  return (await $.ui.panes()).some(pane => pane.id === PANE)
}

async function refreshIfChanged($: EngineInterface): Promise<void> {
  if (isLoading || !(await isOpen($))) return
  const root = await repoRoot($)
  if (root === null) return
  if ((await refSignature($, root)) !== lastSignature) await load($)
}

/** The working tree moves without any ref moving: kept fresh on its own, cheaply. */
async function refreshWork($: EngineInterface): Promise<void> {
  if (isLoading) return
  const g = await read($, graph)
  const work = await workTree($, g?.repo || undefined)
  if (g && !g.error && JSON.stringify(work) !== JSON.stringify(g.work)) {
    await update($, graph, current => (current ? { ...current, work } : current))
  }
  showStatus($, g ? { ...g, work } : null)
}

async function refreshGitHub($: EngineInterface, root: string, force: boolean): Promise<void> {
  const now = await $.clock.now()
  const current = await read($, github)
  if (!force && current && now - current.fetchedAt < GITHUB_TTL) return
  const next = await loadGitHub($, root, now)
  await update($, github, () => next)
}

async function loadMore($: EngineInterface): Promise<void> {
  const g = await read($, graph)
  if (!g || isLoading || g.rows.length >= g.total) return
  await update($, limit, n => n + PAGE)
  await load($)
}

/** The status line: branch, ahead/behind its upstream, uncommitted files. */
function showStatus($: EngineInterface, g: Graph | null): void {
  const work = g?.work
  if (!work) {
    $.ui.status(undefined)
    return
  }
  const changed = work.files.length
  $.ui.status(
    `⎇ ${work.branch}` +
      (work.ahead ? ` ↑${work.ahead}` : '') +
      (work.behind ? ` ↓${work.behind}` : '') +
      (changed ? ` · ${changed} changed` : ''),
  )
}

// ---------------------------------------------------------------- commits Claude made

async function restoreClaude($: EngineInterface, root: string): Promise<void> {
  const kept = await $.store.get(KEYS.claude(root))
  if (Array.isArray(kept)) {
    const hashes = kept.filter((h): h is string => typeof h === 'string')
    await update($, claude, current => (current.length ? current : hashes))
  }
}

async function recordClaudeCommit($: EngineInterface, hash: string): Promise<void> {
  const root = await repoRoot($)
  if (root === null) return
  const next = await update($, claude, list => [hash, ...list.filter(h => h !== hash)].slice(0, 500))
  await $.store.set(KEYS.claude(root), next)
}

// ---------------------------------------------------------------- selection and details

async function select($: EngineInterface, hash: string): Promise<void> {
  const [current, base] = await Promise.all([read($, selected), read($, compareBase)])
  if (current === hash && !base) {
    await clearSelection($)
    return
  }
  await update($, selected, () => hash)
  await update($, diff, () => null)
  await update($, naming, () => null)

  const root = (await read($, graph))?.repo || undefined
  const comparing = base && base !== hash && hash !== WORKTREE ? base : null
  const next = await loadDetail($, root, hash, comparing)
  if ((await read($, selected)) === hash) await update($, detail, () => next)
  $.ui.invalidate('ui.render')
}

async function clearSelection($: EngineInterface): Promise<void> {
  await update($, selected, () => null)
  await update($, detail, () => null)
  await update($, diff, () => null)
  await update($, naming, () => null)
}

async function toggleDiff($: EngineInterface, det: Detail): Promise<void> {
  if ((await read($, diff)) !== null) {
    await update($, diff, () => null)
    return
  }
  const root = (await read($, graph))?.repo || undefined
  const files = await loadPatch($, root, det)
  await update($, diff, () => files)
}

function visibleRows(g: Graph, q: string): GraphRow[] {
  return filterRows(g.rows, q)
}

async function step($: EngineInterface, by: 1 | -1): Promise<void> {
  const [g, q, current] = await Promise.all([read($, graph), read($, query), read($, selected)])
  if (!g) return
  const rows = visibleRows(g, q)
  if (rows.length === 0) return
  const at = rows.findIndex(row => row.hash === current)
  const index = Math.min(rows.length - 1, Math.max(0, at === -1 ? 0 : at + by))
  const next = rows[index]
  if (!next) return
  await showIndex($, index)
  await select($, next.hash)
  await $.ui.scroll({ in: PANE, to: { key: `row-${next.hash}` } }).catch(() => undefined)
}

async function jumpTo($: EngineInterface, name: string): Promise<void> {
  const g = await read($, graph)
  if (!g) return
  const row =
    name === 'HEAD'
      ? g.rows.find(r => r.hash === g.head)
      : g.rows.find(r => r.refs.some(ref => ref.name === name || ref.name.endsWith(`/${name}`)))
  if (!row) {
    $.ui.toast(`${name} is not among the loaded commits. Load more, or pick it in the branch filter.`)
    return
  }
  await showIndex($, visibleRows(g, await read($, query)).findIndex(r => r.hash === row.hash))
  await $.ui.scroll({ in: PANE, to: { key: `row-${row.hash}` }, block: 'center' }).catch(() => undefined)
  await select($, row.hash)
}

async function runSearch($: EngineInterface, text: string): Promise<void> {
  const next: Search | null = text.trim() ? readSearch(text) : null
  await update($, search, () => next)
  await update($, query, () => '')
  await update($, offset, () => 0)
  await update($, limit, () => PAGE)
  await clearSelection($)
  await load($)
}

async function setScope($: EngineInterface, value: Scope): Promise<void> {
  await update($, scope, () => value)
  await $.store.set(KEYS.scope, value)
  await update($, offset, () => 0)
  await update($, limit, () => PAGE)
  await load($)
}

// ---------------------------------------------------------------- git actions (they write: always asked first)

async function confirmGit($: EngineInterface, what: string, args: string[]): Promise<void> {
  let answer = ''
  try {
    answer = await $.ui.ask(`${what}? This runs: git ${args.join(' ')}`, {
      options: ['Run', 'Cancel'],
      header: 'Git',
    })
  } catch {
    return
  }
  if (answer !== 'Run') return
  const root = (await read($, graph))?.repo || undefined
  const ran = await $.process.run(['git', ...args], { cwd: root, timeoutMs: 60000 })
  if (ran.exitCode === 0) {
    $.ui.toast(`git ${args[0]}: done`)
  } else {
    $.ui.toast(`git ${args[0]} failed: ${(ran.stderr || ran.stdout).trim().split('\n')[0] ?? ''}`, { timeoutMs: 10000 })
  }
  await load($)
}

function checkoutTarget(row: GraphRow | undefined, hash: string): string[] {
  const local = row?.refs.find(ref => ref.kind === 'head' || ref.kind === 'branch')
  if (local) return ['checkout', local.name]
  const remote = row?.refs.find(ref => ref.kind === 'remote')
  if (remote) return ['checkout', remote.name.slice(remote.name.indexOf('/') + 1)]
  return ['checkout', '--detach', hash]
}

// ---------------------------------------------------------------- the pane's size

type Size = { columns?: number; rows?: number }

const clamp = (n: number, lo: number, hi: number) => Math.min(hi, Math.max(lo, Math.round(n)))

/** What the pane measured when last drawn: the base a drag resizes from. */
let drawn = { columns: 80, rows: 24, placement: 'dock' as 'dock' | 'inline', treeRows: 0 }

async function savedSize($: EngineInterface): Promise<Size> {
  const kept = await $.store.get(KEYS.size)
  return kept && typeof kept === 'object' ? (kept as Size) : {}
}

async function openPane($: EngineInterface): Promise<void> {
  await load($)
  await $.ui.open({ id: PANE, title: 'Git graph', ...(await savedSize($)) })
  $.ui.invalidate('ui.render')
}

/** A drag on the grip, in cells: wider to the left when docked, taller downwards inline. */
async function resizeBy($: EngineInterface, dx: number, dy: number): Promise<void> {
  const size = await savedSize($)
  const next: Size =
    drawn.placement === 'dock'
      ? { ...size, columns: clamp(drawn.columns - dx, 40, 240) }
      : { ...size, rows: clamp(drawn.rows + dy, 6, 120) }
  await $.store.set(KEYS.size, next)
  await $.ui.open({ id: PANE, title: 'Git graph', ...next })
}

async function opened($: EngineInterface): Promise<string> {
  await openPane($)
  const g = await read($, graph)
  return g?.error ? `Git graph: ${g.error}` : `Git graph opened: ${g?.rows.length ?? 0} of ${g?.total ?? 0} commits.`
}

/** Moves the desktop's page so that the commit at `index` (among the visible rows) is on it. */
async function showIndex($: EngineInterface, index: number): Promise<void> {
  const start = Math.floor(Math.max(0, index) / DESKTOP_PAGE) * DESKTOP_PAGE
  if ((await read($, offset)) !== start) await update($, offset, () => start)
}

// ---------------------------------------------------------------- hooks

function isOurPane(requestId: string, title: string | undefined): boolean {
  return requestId === PANE || requestId.includes(PANE) || title === 'Git graph'
}

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    await $.command.register({
      name: 'git-graph',
      description: 'Show the git graph of this repo in a pane (close: /git-graph close)',
      argumentHint: '[close]',
      immediate: true,
    })
    const [keptScope, keptStashes] = await Promise.all([$.store.get(KEYS.scope), $.store.get(KEYS.stashes)])
    if (typeof keptScope === 'string') await update($, scope, () => keptScope)
    if (typeof keptStashes === 'boolean') await update($, isStashOpen, () => keptStashes)

    $.clock.every(4000, () => {
      void refreshIfChanged($)
    })
    $.clock.every(6000, () => {
      void refreshWork($)
    })
    void refreshWork($)
    if (await isOpen($)) void load($)

    return next(e)
  })

  on('command.run', { command: 'git-graph' }, async ($, e) => {
    if ((e.args ?? '').trim() === 'close') {
      await $.ui.close({ id: PANE })
      return { text: 'Git graph closed.' }
    }
    return { text: await opened($) }
  })

  // The desktop app sends a slash command it does not list as a plain prompt:
  // catch `/git-graph` there too, so it never reaches the model.
  on('prompt.submit', async ($, e, next) => {
    const typed = e.text.trim().match(/^\/git-graph(?:\s+(close))?$/)
    if (!typed) return next(e)
    if (typed[1] === 'close') {
      await $.ui.close({ id: PANE })
      return { drop: 'Git graph closed.' }
    }
    return { drop: await opened($) }
  }).catch(($, e, next) => next(e))

  // A commit Claude makes through its shell tools is marked in the graph.
  on('tool.call', async ($, e, next) => {
    const command = String((e as { command?: unknown }).command ?? '')
    const isShell = e.tool === 'Bash' || e.tool === 'PowerShell'
    if (!isShell || !/\bgit\b[\s\S]*\bcommit\b/.test(command)) return next(e)
    const before = await headOf($)
    const ran = await next(e)
    const after = await headOf($)
    if (after && after !== before) await recordClaudeCommit($, after)
    void refreshIfChanged($)

    return ran
  }).catch(($, e, next) => next(e))

  // Every write to this plugin's state redraws the pane: a surface that names
  // the pane's instance otherwise (the desktop) does not redraw on the write alone.
  on('state.set', { plugin: 'git-graph' }, async ($, e, next) => {
    const written = await next(e)
    $.ui.invalidate('ui.render')
    return written
   }).catch(($, e, next) => next(e))

  on('ui.message', async ($, e, next) => {
    if (e.element !== 'grip') return next(e)
    const data = e.data as { dx?: unknown; dy?: unknown } | null
    const dx = typeof data?.dx === 'number' ? data.dx : 0
    const dy = typeof data?.dy === 'number' ? data.dy : 0
    await resizeBy($, dx, dy)

    return {}
  })

  // Scrolling near the end loads the next page of history.
  on('ui.scroll', { requestId: PANE }, async ($, e, next) => {
    const moved = await next(e)
    if (e.by > 0 && e.offset + drawn.rows >= drawn.treeRows - 15) void loadMore($)

    return moved
   }).catch(($, e, next) => next(e))

  on('turn.complete', async ($, e, next) => {
    const ran = await next(e)
    void refreshIfChanged($)
    void refreshWork($)

    return ran
  })

  on('ui.render', { component: 'Pane' }, async ($, e, next) => {
    // Matched by hand: a surface may name the pane's instance otherwise than its id.
    if (!isOurPane(e.requestId, e.props.title)) return next(e)
    const ui = $.ui.resolve(e)
    const { Box, Text, Button, Code } = ui
    // The desktop pane goes blank when it holds too many rows: it draws one page at a time.
    const lite = e.surface === 'desktop'
    const start = lite ? await read($, offset) : 0
    const Svg = 'Svg' in ui ? ui.Svg : undefined
    const Client = 'Client' in ui ? ui.Client : undefined
    const Input = 'Input' in ui ? ui.Input : undefined
    const Select = 'Select' in ui ? ui.Select : undefined

    const [helpOpen, moreOpen] = await Promise.all([read($, isHelpOpen), read($, isMoreOpen)])
    const [g, sel, det, files, which, q, narrowed, base, mine, gh, stashesOpen, askName] = await Promise.all([
      read($, graph),
      read($, selected),
      read($, detail),
      read($, diff),
      read($, scope),
      read($, query),
      read($, search),
      read($, compareBase),
      read($, claude),
      read($, github),
      read($, isStashOpen),
      read($, naming),
    ])
    const now = await $.clock.now()
    const cols = Math.max(40, e.props.bodyColumns ?? 80)
    drawn = { ...drawn, columns: e.props.bodyColumns ?? 80, rows: e.props.scroll?.bodyRows ?? 24, placement: e.props.placement }

    if (g === null) {
      return <Text color={MUTED}>Loading the git graph…</Text>
    }

    const byClaude = new Set(mine)
    const prFor = (ref: string): PullRequest | undefined => gh?.prs[ref.replace(/^[^/]+\//, '')] ?? gh?.prs[ref]

    // -------- header: title, filters, size grip
    const scopeOptions = [
      { value: 'all', label: 'All branches' },
      { value: 'current', label: 'Current branch' },
      { value: 'local', label: 'Local only (no remotes)' },
      ...g.branches.slice(0, 40).map(b => ({ value: `branch:${b}`, label: `Branch: ${b}` })),
    ]
    const jumpOptions = [
      { value: '', label: 'Jump to…' },
      { value: 'HEAD', label: 'HEAD' },
      ...g.branches.slice(0, 40).map(b => ({ value: b, label: b })),
      ...g.tags.slice(0, 20).map(t => ({ value: t, label: `tag ${t}` })),
    ]

    const work0 = g.work
    const header = (
      <Box flexDirection="column" marginBottom={1}>
        <Box flexDirection="row" alignItems="center" gap={1}>
          <Text bold>{g.repo ? g.repo.split(/[\\/]/).pop() : 'Git graph'}</Text>
          {work0?.branch ? (
            <Text color="#4FA3F7">
              {`⎇ ${work0.branch}${work0.ahead ? ` ↑${work0.ahead}` : ''}${work0.behind ? ` ↓${work0.behind}` : ''}`}
            </Text>
          ) : null}
          <Box flexGrow={1} flexShrink={1} minWidth={0}>
            <Text color={MUTED} wrap="truncate">
              {g.rows.length ? `${g.rows.length === g.total ? g.total : `${g.rows.length} of ${g.total}`} commits` : ''}
              {gh?.error ? ' · GitHub offline' : ''}
            </Text>
          </Box>
          <Button key="refresh" plain label="⟳"  onPress={() => load($)} />
          <Button key="help" plain label="?"  onPress={() => update($, isHelpOpen, open => !open).then(() => undefined)} />
          {Client ? (
            <Client key="grip" module="./grip.tsx" props={{ axis: e.props.placement === 'dock' ? 'x' : 'y' }} />
          ) : null}
        </Box>
        <Box flexDirection="row" alignItems="center" gap={1} flexWrap="wrap">
          {Select ? (
            <Select
              key="scope"
              options={scopeOptions.some(o => o.value === which) ? scopeOptions : [...scopeOptions, { value: which, label: which }]}
              value={which}
              onSelect={value => setScope($, value)}
            />
          ) : (
            <Button
              key="scope"
              label={which === 'all' ? 'All branches' : which === 'current' ? 'Current branch' : which}

              onPress={() => setScope($, which === 'all' ? 'current' : which === 'current' ? 'local' : 'all')}
            />
          )}
          {Select ? (
            <Select key="jump" options={jumpOptions} value="" onSelect={value => (value ? jumpTo($, value) : undefined)} />
          ) : (
            <Button key="jump-head" label="Jump to HEAD"  onPress={() => jumpTo($, 'HEAD')} />
          )}
        </Box>
        {Input ? (
          <Input
            key="search"
            placeholder="Filter commits… (Enter searches all history, path:… for a file)"
            value={q}
            submitLabel="search all"
            onInput={value => update($, query, () => value).then(() => update($, offset, () => 0))}
            onSubmit={value => runSearch($, value)}
          />
        ) : null}
        {narrowed || q ? (
          <Box flexDirection="row" gap={1} alignItems="center">
            <Text color="suggestion">
              {narrowed
                ? `${narrowed.mode === 'path' ? 'History of' : narrowed.mode === 'hash' ? 'From commit' : 'Searching'} "${narrowed.q}"`
                : `Filtering "${q}"`}
            </Text>
            <Text color={MUTED}>{`${narrowed ? g.total : filterRows(g.rows, q).length} found`}</Text>
            <Button key="clear" plain label="✕ clear"  onPress={() => runSearch($, '')} />
          </Box>
        ) : null}
        {helpOpen ? (
          <Box flexDirection="column" borderStyle="round" borderDimColor paddingX={1}>
            <Text color={MUTED}>Keys (click the pane first): j/k next/prev · h HEAD · f search · r refresh · d diff · c compare</Text>
            <Text color={MUTED}>Click a commit for its full message and details; click a file there to see its history.</Text>
            <Text color={MUTED}>☁ in sync with origin · ↑ ahead · ↓ behind · ✻ made by Claude · ✓ ✗ ● CI</Text>
          </Box>
        ) : null}
      </Box>
    )

    if (g.error) {
      return (
        <Box flexDirection="column">
          {header}
          <Text color="warning">{g.error}</Text>
        </Box>
      )
    }

    const graphCols = g.width * 2 + 1
    const rows = visibleRows(g, q)

    // -------- one commit row: graph slice, refs and badges, message, author, hover card
    const commitRow = (row: GraphRow) => {
      const badges = pills(row.refs).slice(0, 3)
      const prs = new Map<number, PullRequest>()
      for (const pill of badges) {
        const pr = pill.branch ? prFor(pill.branch) : undefined
        if (pr) prs.set(pr.number, pr)
      }
      const ci = prs.size === 0 ? gh?.runs[row.hash] : undefined
      const isClaude = byClaude.has(row.hash)
      const isSel = row.hash === sel || row.hash === base
      const meta = `${shortAuthor(row.author)} · ${shortAgo(row.time, now)}`
      const badgeChars = badges.reduce((n, p) => n + p.label.length + 5, 0) + prs.size * 7 + (isClaude ? 2 : 0) + (ci ? 2 : 0)
      const room = cols - graphCols - badgeChars - meta.length - 6
      const subject = clip(shortSubject(row.subject), Math.max(14, room))
      const graphCell = Svg ? (
        <Svg source={rowSvg(row, g.width)} alt={`commit ${row.short}`} height={ROW} />
      ) : (
        <Box flexDirection="row" flexShrink={0}>
          {rowCells(row, g.width).map(cell => (
            <Text color={COLORS[cell.color]}>{cell.glyph + ' '}</Text>
          ))}
        </Box>
      )

      return (
        <Box
          key={`row-${row.hash}`}
          flexDirection="row"
          alignItems="center"
          backgroundColor={isSel ? 'rgba(79,163,247,0.18)' : undefined}
        >
          <Box flexShrink={0}>{graphCell}</Box>
          <Box flexDirection="row" alignItems="center" gap={1} flexGrow={1} flexShrink={1} minWidth={0}>
            {badges.map(pill => {
              const track = pill.kind === 'head' || pill.kind === 'branch' ? g.tracks[pill.label] : undefined
              const drift = track
                ? `${track.ahead ? ` ↑${track.ahead}` : ''}${track.behind ? ` ↓${track.behind}` : ''}${track.isGone ? ' ⚠' : ''}`
                : ''
              const mark = drift || (pill.isSynced ? ' ☁' : '')
              return (
                <Text backgroundColor={REF_STYLE[pill.kind].bg} color={REF_STYLE[pill.kind].fg} bold={pill.kind === 'head'}>
                  {` ${pill.kind === 'head' ? '● ' : pill.kind === 'tag' ? '◆ ' : ''}${pill.label}${mark} `}
                </Text>
              )
            })}
            {[...prs.values()].map(pr => (
              <Text color={pr.state === 'MERGED' ? 'merged' : pr.state === 'OPEN' ? 'success' : 'inactive'}>
                {`#${pr.number}${pr.isDraft ? ' draft' : ''}${pr.checks !== 'none' ? ' ' + CHECK_GLYPH[pr.checks] : ''}`}
              </Text>
            ))}
            <Box flexGrow={1} flexShrink={1} minWidth={0}>
              <Button
                key={`c-${row.hash}`}
                plain
                label={subject}
                                onPress={() => select($, row.hash)}
              />
            </Box>
            {isClaude ? <Text color="claude">✻</Text> : null}
            {ci && ci !== 'none' ? <Text color={CHECK_COLOR[ci]}>{CHECK_GLYPH[ci]}</Text> : null}
            <Text color={MUTED} wrap="truncate">
              {meta}
            </Text>
          </Box>
        </Box>
      )
    }

    // -------- the working tree and stashes, above the history
    const work = g.work
    const changed = work ? work.files.length : 0
    const worktreeRow =
      work && changed > 0 && (which === 'all' || which === 'current' || which === 'local') && !narrowed ? (
        <Box
          key={`row-${WORKTREE}`}
          flexDirection="row"
          alignItems="center"
          gap={1}
          backgroundColor={sel === WORKTREE ? 'rgba(79,163,247,0.18)' : undefined}
        >
          <Text color="warning">{' ◌ '.padEnd(graphCols)}</Text>
          <Button
            key="c-worktree"
            plain
            label={
              'Uncommitted changes · ' +
              [
                work.staged ? `${work.staged} staged` : '',
                work.modified ? `${work.modified} modified` : '',
                work.untracked ? `${work.untracked} untracked` : '',
                work.conflicted ? `${work.conflicted} conflicted` : '',
              ]
                .filter(Boolean)
                .join(' · ')
            }
            onPress={() => select($, WORKTREE)}
          />
        </Box>
      ) : null

    const stashSection =
      g.stashes.length > 0 && !narrowed ? (
        <Box flexDirection="column">
          <Button
            key="stashes"
            plain

            label={`${stashesOpen ? '▾' : '▸'} Stashes (${g.stashes.length})`}
            onPress={async () => {
              const isOpenNow = await update($, isStashOpen, open => !open)
              await $.store.set(KEYS.stashes, isOpenNow)
            }}
          />
          {stashesOpen
            ? g.stashes.map(stash => (
                <Box key={`row-${stash.hash}`} flexDirection="row" gap={1}>
                  <Text color={MUTED}>{'   ' + stash.ref}</Text>
                  <Button key={`c-${stash.hash}`} plain label={clip(stash.subject, cols - 30)} onPress={() => select($, stash.hash)} />
                  <Text color={MUTED}>{ago(stash.time, now)}</Text>
                </Box>
              ))
            : null}
        </Box>
      ) : null

    // -------- the details card
    const card = det && sel && (det.hash === sel || det.hash.startsWith(sel)) ? detailCard(det) : sel ? <Text color={MUTED}>Loading…</Text> : null

    function detailCard(d: Detail) {
      const row = g?.rows.find(r => r.hash === d.hash)
      const stash = g?.stashes.find(s => s.hash === d.hash)
      const added = d.files.reduce((n, f) => n + f.added, 0)
      const deleted = d.files.reduce((n, f) => n + f.deleted, 0)
      const ask = (text: string) => () => $.prompt.fill({ text }).then(() => undefined)

      return (
        <Box flexDirection="column" borderStyle="round" borderDimColor paddingX={1} marginBottom={1}>
          <Box flexDirection="row" gap={1}>
            <Box flexGrow={1} flexShrink={1} minWidth={0}>
              <Text bold wrap="truncate">
                {d.subject}
              </Text>
            </Box>
            {d.kind === 'commit' ? <Text color={MUTED}>{d.short}</Text> : null}
          </Box>
          <Text color={MUTED}>
            {d.kind === 'commit' ? `${d.author} · ${ago(d.time, now)} (${new Date(d.time * 1000).toISOString().slice(0, 16).replace('T', ' ')} UTC) · ` : ''}
            {d.parents.length > 1 ? `merge of ${d.parents.length} parents · ` : ''}
            {stash ? `${stash.ref} · ` : ''}
            <Text color="diffAdded">+{added}</Text> <Text color="diffRemoved">−{deleted}</Text> · {d.files.length}{' '}
            {d.files.length === 1 ? 'file' : 'files'}
            {byClaude.has(d.hash) ? ' · made by Claude' : ''}
          </Text>
          {d.body ? <Text color={MUTED}>{clip(d.body, 600)}</Text> : null}

          <Box flexDirection="column" marginTop={1}>
            {d.files.slice(0, 10).map((f, i) => (
              <Box flexDirection="row">
                <Text color="diffAdded">{`+${f.added}`.padStart(5)}</Text>
                <Text color="diffRemoved">{` −${f.deleted}`.padEnd(7)}</Text>
                <Button key={`file-${i}`} plain  label={clip(f.path, cols - 16)} onPress={() => runSearch($, `path:${f.path}`)} />
              </Box>
            ))}
            {d.files.length > 10 ? <Text color={MUTED}>…and {d.files.length - 10} more (Show diff lists them all)</Text> : null}
            {d.kind === 'worktree' && g?.work
              ? g.work.files
                  .filter(f => f.code === '??')
                  .slice(0, 20)
                  .map(f => <Text color={MUTED}>{`   new   ${f.path}`}</Text>)
              : null}
            {d.files.length > 0 ? <Text color={MUTED}>Click a file to see its history.</Text> : <Text color={MUTED}>No file changes.</Text>}
          </Box>

          <Box flexDirection="row" gap={1} marginTop={1} flexWrap="wrap">
            <Button key="diff" hotkey="d" label={files ? 'Hide diff' : 'Show diff'} onPress={() => toggleDiff($, d)} />
            {d.kind === 'commit' ? (
              <>
                <Button key="ask" label="Explain" onPress={ask(`Explain commit ${d.short} ("${d.subject}"): what changed and why. Use git show ${d.short}.`)} />
                <Button key="review" label="Review" onPress={ask(`Review commit ${d.short} ("${d.subject}") for bugs and risks. Use git show ${d.short}.`)} />
                <Button
                  key="compare"
                  hotkey="c"
                  label="Compare with…"
                  onPress={async () => {
                    await update($, compareBase, () => d.hash)
                    $.ui.toast(`Comparing from ${d.short}: pick another commit`)
                  }}
                />
                <Button
                  key="copy"
                  label="Copy hash"
                  onPress={async press => {
                    const copied = await $.ui.copy({ text: d.hash, surface: press.surface })
                    if (copied.isCopied) {
                      $.ui.toast(`Copied ${d.short}`)
                    } else {
                      await $.prompt.fill({ text: d.hash, mode: 'insert' })
                      $.ui.toast('Hash put in the prompt box')
                    }
                  }}
                />
              </>
            ) : null}
            {d.kind === 'compare' ? (
              <>
                <Button key="notes" label="Release notes" onPress={ask(`Write release notes for ${d.subject}, grouped by theme. Use git log ${d.subject} and git diff --stat ${d.subject}.`)} />
                <Button key="review-range" label="Review range" onPress={ask(`Review the changes in ${d.subject} for bugs and risks. Use git diff ${d.subject}.`)} />
              </>
            ) : null}
            {d.kind === 'worktree' ? (
              <>
                <Button key="message" label="Write commit message" onPress={ask('Write a commit message for my uncommitted changes. Use git status and git diff HEAD. Do not commit.')} />
                <Button key="review-work" label="Review my changes" onPress={ask('Review my uncommitted changes for bugs and risks. Use git diff HEAD. Do not change any file.')} />
              </>
            ) : null}
            {base ? (
              <Button
                key="cancel-compare"
                label="Stop comparing"

                onPress={async () => {
                  await update($, compareBase, () => null)
                  await clearSelection($)
                }}
              />
            ) : null}
            {d.kind === 'commit' ? (
              <Button
                key="more"
                plain

                label={moreOpen ? 'Less ▾' : 'More ▸'}
                onPress={() => update($, isMoreOpen, open => !open).then(() => undefined)}
              />
            ) : null}
            <Button key="close-detail" plain label="✕"  onPress={() => clearSelection($)} />
          </Box>

          {d.kind === 'commit' && moreOpen ? (
            <Box flexDirection="column" marginTop={1}>
              <Box flexDirection="row" gap={1} flexWrap="wrap">
                <Button key="since" label="Summarize since this commit" onPress={ask(`Summarize what changed from ${d.short} to HEAD as release notes, grouped by theme. Use git log ${d.short}..HEAD.`)} />
              </Box>
              <Text color="warning">These change your repository; each asks before it runs:</Text>
              <Box flexDirection="row" gap={1} flexWrap="wrap">
                {stash ? (
                  <Button key="a-apply" label="Apply stash" onPress={() => confirmGit($, `Apply ${stash.ref}`, ['stash', 'apply', stash.ref])} />
                ) : (
                  <>
                    <Button key="a-checkout" label="Checkout" onPress={() => {
                      const args = checkoutTarget(row, d.hash)
                      return confirmGit($, `Check out ${args[args.length - 1]}`, args)
                    }} />
                    <Button key="a-branch" label="New branch…" onPress={() => update($, naming, () => 'branch' as Naming).then(() => undefined)} />
                    <Button key="a-tag" label="Tag…" onPress={() => update($, naming, () => 'tag' as Naming).then(() => undefined)} />
                    <Button key="a-pick" label="Cherry-pick" onPress={() => confirmGit($, `Cherry-pick ${d.short} onto the current branch`, d.parents.length > 1 ? ['cherry-pick', '-m', '1', d.hash] : ['cherry-pick', d.hash])} />
                    <Button key="a-revert" label="Revert" onPress={() => confirmGit($, `Revert ${d.short} with a new commit`, d.parents.length > 1 ? ['revert', '--no-edit', '-m', '1', d.hash] : ['revert', '--no-edit', d.hash])} />
                  </>
                )}
              </Box>
              {askName && Input ? (
                <Input
                  key="name"
                  label={askName === 'branch' ? `New branch at ${d.short}` : `Tag ${d.short} as`}
                  placeholder={askName === 'branch' ? 'feat/my-branch' : 'v1.0.0'}
                  submitLabel="create"
                  autoFocus
                  onSubmit={async value => {
                    const name = value.trim()
                    await update($, naming, () => null)
                    if (!name) return
                    await confirmGit(
                      $,
                      askName === 'branch' ? `Create branch ${name} at ${d.short}` : `Tag ${d.short} as ${name}`,
                      askName === 'branch' ? ['branch', name, d.hash] : ['tag', name, d.hash],
                    )
                  }}
                />
              ) : null}
            </Box>
          ) : null}

          {files ? (
            <Box flexDirection="column" marginTop={1}>
              {files.length === 0 ? <Text color={MUTED}>No textual changes.</Text> : null}
              {files.map(file => (
                <Box flexDirection="column" marginBottom={1}>
                  <Text bold>{file.path}</Text>
                  {file.hunks ? (
                    <Code source={file.hunks} format="diff" path={file.path} wrap="truncate-end" />
                  ) : (
                    <Text color={MUTED}>Binary, or a rename only.</Text>
                  )}
                </Box>
              ))}
            </Box>
          ) : null}
        </Box>
      )
    }

    const compareHint = base && !det ? (
      <Box flexDirection="row" gap={1} marginBottom={1}>
        <Text color="suggestion">Comparing from {base.slice(0, 7)}: pick another commit.</Text>
        <Button key="cancel-compare-hint" label="Cancel"  onPress={() => update($, compareBase, () => null).then(() => undefined)} />
      </Box>
    ) : null

    const more =
      g.rows.length < g.total && !q && !lite ? (
        <Box marginTop={1}>
          <Button key="more" label={`Load ${Math.min(PAGE, g.total - g.rows.length)} more`} onPress={() => loadMore($)} />
        </Box>
      ) : null

    drawn.treeRows = rows.length + 8 + (card ? 20 + (det?.files.length ?? 0) : 0) + (stashesOpen ? g.stashes.length : 0)

    return (
      <Box flexDirection="column">
        {header}
        {compareHint}
        {card}
        {worktreeRow}
        {stashSection}
        {rows.length === 0 ? (
          <Box flexDirection="column" marginTop={1}>
            <Text>No commit matches.</Text>
            <Text color={MUTED}>{q ? 'Press Enter to search the whole history instead of the loaded commits.' : 'Try another branch filter.'}</Text>
          </Box>
        ) : null}
        <Box flexDirection="column">{(lite ? rows.slice(start, start + DESKTOP_PAGE) : rows).map(commitRow)}</Box>
        {lite && rows.length > DESKTOP_PAGE ? (
          <Box flexDirection="row" gap={1} alignItems="center" marginTop={1}>
            {start > 0 ? (
              <Button key="newer" label="◂ Newer" onPress={() => update($, offset, n => Math.max(0, n - DESKTOP_PAGE)).then(() => undefined)} />
            ) : null}
            <Text color={MUTED}>
              {start + 1}–{Math.min(start + DESKTOP_PAGE, rows.length)} of {rows.length}
            </Text>
            {start + DESKTOP_PAGE < rows.length ? (
              <Button key="older" label="Older ▸" onPress={() => update($, offset, n => n + DESKTOP_PAGE).then(() => undefined)} />
            ) : g.rows.length < g.total && !q ? (
              <Button
                key="older-load"
                label="Older ▸"
                onPress={async () => {
                  await loadMore($)
                  await update($, offset, n => n + DESKTOP_PAGE)
                }}
              />
            ) : null}
          </Box>
        ) : null}
        {more}
        <Box flexDirection="row" gap={1} marginTop={1}>
          <Button key="k-next" plain hotkey="j" label="next"  onPress={() => step($, 1)} />
          <Button key="k-prev" plain hotkey="k" label="prev"  onPress={() => step($, -1)} />
          <Button key="k-head" plain hotkey="h" label="HEAD"  onPress={() => jumpTo($, 'HEAD')} />
          {Input ? (
            <Button key="k-find" plain hotkey="f" label="search"  onPress={() => $.ui.focus({ requestId: PANE, key: 'search' }).then(() => undefined)} />
          ) : null}
          <Button key="k-refresh" plain hotkey="r" label="refresh"  onPress={() => load($)} />
        </Box>
      </Box>
    )
  }).catch(($, e, next) => {
    // A tree that threw, ran out of time, or that the surface refused: say why in the pane.
    const { Box, Text, Button } = $.ui.resolve(e)
    const failure = next.error
    return (
      <Box flexDirection="column">
        <Text color="error">git-graph could not draw ({failure?.kind ?? 'unknown'}):</Text>
        <Text>{failure?.message ?? 'no reason given'}</Text>
        <Button key="retry" label="Retry" onPress={() => load($)} />
      </Box>
    )
  })

  // A Client (the resize grip) that failed on a surface: say so, then draw without it.
  on('ui.fault', async ($, e, next) => {
    $.ui.toast(`git-graph: ${e.reason}`, { timeoutMs: 10000 })
    return next(e)
  })
}

