import type {
  Checks,
  FileDiff,
  FileStat,
  GraphRow,
  PullRequest,
  Ref,
  RefKind,
  Search,
  Seg,
  Stash,
  Track,
  WorkTree,
} from '../types'

export const COLORS = [
  '#4FA3F7',
  '#F5B400',
  '#E5437A',
  '#2BB3A3',
  '#B07CE8',
  '#E8743B',
  '#7CB342',
  '#F06292',
]

export const LANE = 14
export const ROW = 24

const FS = '\x1f'
const RS = '\x1e'

/** The `--format` the log is read with: hash, parents, author, time, refs, subject. */
export const LOG_FORMAT = ['%H', '%P', '%an', '%at', '%D', '%s'].join('%x1f') + '%x1e'

export type RawCommit = {
  hash: string
  parents: string[]
  author: string
  time: number
  refs: string
  subject: string
}

export function parseLog(stdout: string): RawCommit[] {
  return stdout
    .split(RS)
    .map(record => record.replace(/^\s+/, ''))
    .filter(record => record.length > 0)
    .map(record => {
      const [hash, parents, author, time, refs, subject] = record.split(FS)
      return {
        hash: hash ?? "",
        parents: parents ? parents.split(' ').filter(Boolean) : [],
        author: author ?? '',
        time: Number(time) || 0,
        refs: refs ?? '',
        subject: subject ?? '',
      }
    })
}

export function parseRefs(decoration: string, remotes: readonly string[]): Ref[] {
  const refs: Ref[] = []
  for (const part of decoration.split(', ').map(p => p.trim()).filter(Boolean)) {
    if (part.startsWith('HEAD -> ')) {
      refs.push({ name: part.slice(8), kind: 'head' })
    } else if (part === 'HEAD') {
      refs.push({ name: 'HEAD', kind: 'head' })
    } else if (part.startsWith('tag: ')) {
      refs.push({ name: part.slice(5), kind: 'tag' })
    } else if (part.endsWith('/HEAD')) {
      continue
    } else if (remotes.some(remote => part.startsWith(remote + '/'))) {
      refs.push({ name: part, kind: 'remote' })
    } else {
      refs.push({ name: part, kind: 'branch' })
    }
  }
  return refs
}

/**
 * Lays commits (newest first, topological order) out in lanes, VS Code style:
 * each row carries the strokes of its own slice, so rows draw independently.
 */
export function layout(
  commits: readonly RawCommit[],
  remotes: readonly string[] = [],
): { rows: GraphRow[]; width: number } {
  const lanes: (string | null)[] = []
  const laneColor: number[] = []
  let nextColor = 0
  let width = 1
  const firstFree = () => {
    const free = lanes.indexOf(null)
    return free === -1 ? lanes.length : free
  }

  const rows = commits.map(commit => {
    const before = lanes.slice()
    const beforeColor = laneColor.slice()
    const segs: Seg[] = []

    let lane = lanes.indexOf(commit.hash)
    if (lane === -1) {
      lane = firstFree()
      lanes[lane] = commit.hash
      laneColor[lane] = nextColor++ % COLORS.length
    }
    const color = laneColor[lane] ?? 0

    before.forEach((hash, k) => {
      if (hash === null || hash === undefined) return
      if (hash === commit.hash) {
        segs.push({ x1: k, y1: 0, x2: lane, y2: 1, color: beforeColor[k] ?? 0 })
        if (k !== lane) lanes[k] = null
      } else {
        segs.push({ x1: k, y1: 0, x2: k, y2: 2, color: beforeColor[k] ?? 0 })
      }
    })

    const [first, ...rest] = commit.parents
    lanes[lane] = first ?? null
    if (first) segs.push({ x1: lane, y1: 1, x2: lane, y2: 2, color })

    for (const parent of rest) {
      let target = lanes.indexOf(parent)
      if (target === -1) {
        target = firstFree()
        lanes[target] = parent
        laneColor[target] = nextColor++ % COLORS.length
      }
      segs.push({ x1: lane, y1: 1, x2: target, y2: 2, color: laneColor[target] ?? 0 })
    }

    width = Math.max(width, before.length, lanes.length)
    while (lanes.length > 0 && lanes[lanes.length - 1] === null) {
      lanes.pop()
    }

    return {
      hash: commit.hash,
      short: commit.hash.slice(0, 7),
      subject: commit.subject,
      author: commit.author,
      time: commit.time,
      refs: parseRefs(commit.refs, remotes),
      lane,
      color,
      isMerge: commit.parents.length > 1,
      segs,
    }
  })

  return { rows, width }
}

const laneX = (k: number) => 8 + k * LANE
const rowY = (y: 0 | 1 | 2) => (y * ROW) / 2

/** One row's slice of the graph as an SVG document. */
export function rowSvg(row: GraphRow, width: number): string {
  const w = 16 + (width - 1) * LANE
  const paths = row.segs.map(seg => {
    const x1 = laneX(seg.x1)
    const x2 = laneX(seg.x2)
    const y1 = rowY(seg.y1)
    const y2 = rowY(seg.y2)
    const mid = (y1 + y2) / 2
    const d =
      x1 === x2
        ? `M${x1} ${y1}V${y2}`
        : `M${x1} ${y1}C${x1} ${mid} ${x2} ${mid} ${x2} ${y2}`
    return `<path d="${d}" stroke="${COLORS[seg.color]}" stroke-width="2" fill="none"/>`
  })
  const cx = laneX(row.lane)
  const fill = COLORS[row.color]
  const dot = row.isMerge
    ? `<circle cx="${cx}" cy="12" r="5" fill="${fill}"/><circle cx="${cx}" cy="12" r="2.2" fill="#ffffff"/>`
    : `<circle cx="${cx}" cy="12" r="4" fill="${fill}"/>`
  return `<svg xmlns="http://www.w3.org/2000/svg" width="${w}" height="${ROW}" viewBox="0 0 ${w} ${ROW}">${paths.join('')}${dot}</svg>`
}

export type Cell = { glyph: string; color: number }

/** One row's slice of the graph as terminal cells, for surfaces without Svg. */
export function rowCells(row: GraphRow, width: number): Cell[] {
  const cells: Cell[] = []
  for (let k = 0; k < width; k++) {
    if (k === row.lane) {
      cells.push({ glyph: row.isMerge ? '◉' : '●', color: row.color })
      continue
    }
    const through = row.segs.find(s => s.x1 === k && s.x2 === k)
    const joins = row.segs.find(s => s.x1 === k && s.x2 !== k)
    const forks = row.segs.find(s => s.x2 === k && s.x1 !== k)
    if (through) cells.push({ glyph: '│', color: through.color })
    else if (joins) cells.push({ glyph: '╯', color: joins.color })
    else if (forks) cells.push({ glyph: '╮', color: forks.color })
    else cells.push({ glyph: ' ', color: 0 })
  }
  return cells
}

export function parseNumstat(stdout: string): FileStat[] {
  return stdout
    .split('\n')
    .map(line => line.split('\t'))
    .filter(parts => parts.length >= 3)
    .map(([added, deleted, ...path]) => ({
      path: path.join('\t'),
      added: Number(added) || 0,
      deleted: Number(deleted) || 0,
    }))
}

/** Splits `git show --format= --patch` output into per-file hunks, bounded. */
export function splitPatch(patch: string, maxChars = 60000, maxFiles = 20): FileDiff[] {
  const files: FileDiff[] = []
  let used = 0
  for (const chunk of patch.split(/^diff --git /m).slice(1)) {
    if (files.length >= maxFiles || used >= maxChars) break
    const header = chunk.slice(0, chunk.indexOf('\n'))
    const plus = chunk.match(/^\+\+\+ b\/(.*)$/m)
    const path = plus?.[1] ?? header.replace(/^a\/(.*) b\/.*$/, '$1')
    const at = chunk.search(/^@@/m)
    if (at === -1) {
      files.push({ path, hunks: '' })
      continue
    }
    let hunks = chunk.slice(at).replace(/\n$/, '')
    if (used + hunks.length > maxChars) {
      const cut = hunks.lastIndexOf('\n@@', maxChars - used)
      if (cut <= 0) break
      hunks = hunks.slice(0, cut)
    }
    used += hunks.length
    files.push({ path, hunks })
  }
  return files
}

export function ago(seconds: number, now: number): string {
  const s = Math.max(0, Math.round(now / 1000 - seconds))
  if (s < 60) return 'just now'
  const m = Math.round(s / 60)
  if (m < 60) return `${m}m ago`
  const h = Math.round(m / 60)
  if (h < 48) return `${h}h ago`
  const d = Math.round(h / 24)
  if (d < 60) return `${d}d ago`
  const mo = Math.round(d / 30)
  if (mo < 24) return `${mo}mo ago`
  return `${Math.round(mo / 12)}y ago`
}

export function clip(text: string, max: number): string {
  return text.length <= max ? text : text.slice(0, Math.max(1, max - 1)) + '…'
}

/** Keeps only the parents a result holds, so a filtered log draws no lanes into nowhere. */
export function closeOver(commits: readonly RawCommit[]): RawCommit[] {
  const present = new Set(commits.map(c => c.hash))
  return commits.map(c => ({ ...c, parents: c.parents.filter(p => present.has(p)) }))
}

/** `git status --porcelain=v2 --branch`. */
export function parseStatus(stdout: string): WorkTree {
  const work: WorkTree = {
    branch: '',
    ahead: 0,
    behind: 0,
    staged: 0,
    modified: 0,
    untracked: 0,
    conflicted: 0,
    files: [],
  }
  for (const line of stdout.split('\n')) {
    if (line.startsWith('# branch.head ')) {
      work.branch = line.slice(14).trim()
    } else if (line.startsWith('# branch.ab ')) {
      const m = line.match(/\+(\d+) -(\d+)/)
      work.ahead = Number(m?.[1] ?? 0)
      work.behind = Number(m?.[2] ?? 0)
    } else if (line.startsWith('1 ') || line.startsWith('2 ')) {
      const parts = line.split(' ')
      const xy = parts[1] ?? '..'
      const rest = parts.slice(line.startsWith('1 ') ? 8 : 9).join(' ')
      const path = rest.split('\t')[0] ?? rest
      if (xy[0] !== '.') work.staged++
      if (xy[1] !== '.') work.modified++
      work.files.push({ path, code: xy.replace(/\./g, ' ') })
    } else if (line.startsWith('u ')) {
      work.conflicted++
      work.files.push({ path: line.split(' ').slice(10).join(' '), code: 'UU' })
    } else if (line.startsWith('? ')) {
      work.untracked++
      work.files.push({ path: line.slice(2), code: '??' })
    }
  }
  return work
}

/** `git for-each-ref --format=%(refname:short)%09%(upstream:short)%09%(upstream:track) refs/heads`. */
export function parseTracks(stdout: string): Record<string, Track> {
  const tracks: Record<string, Track> = {}
  for (const line of stdout.split('\n')) {
    const [name, upstream, track] = line.split('\t')
    if (!name || !upstream) continue
    tracks[name] = {
      upstream,
      ahead: Number(track?.match(/ahead (\d+)/)?.[1] ?? 0),
      behind: Number(track?.match(/behind (\d+)/)?.[1] ?? 0),
      isGone: (track ?? '').includes('gone'),
    }
  }
  return tracks
}

/** `git stash list --format=%H%x1f%gd%x1f%s%x1f%at`. */
export function parseStashes(stdout: string): Stash[] {
  return stdout
    .split('\n')
    .map(line => line.split(FS))
    .filter(parts => parts.length >= 4 && parts[0])
    .map(([hash, ref, subject, time]) => ({
      hash: hash ?? '',
      ref: ref ?? '',
      subject: subject ?? '',
      time: Number(time) || 0,
    }))
}

type CheckRun = { conclusion?: string | null; status?: string | null; state?: string | null }

export function rollup(checks: readonly CheckRun[] | null | undefined): Checks {
  if (!checks || checks.length === 0) return 'none'
  const bad = ['FAILURE', 'ERROR', 'TIMED_OUT', 'CANCELLED', 'ACTION_REQUIRED', 'STARTUP_FAILURE']
  if (checks.some(c => bad.includes((c.conclusion ?? c.state ?? '').toUpperCase()))) return 'fail'
  if (
    checks.some(
      c =>
        (c.status && c.status.toUpperCase() !== 'COMPLETED') ||
        ['PENDING', 'EXPECTED'].includes((c.state ?? '').toUpperCase()),
    )
  ) {
    return 'pending'
  }
  return 'pass'
}

/** `gh pr list --json number,state,isDraft,headRefName,url,statusCheckRollup`, newest first. */
export function parsePrs(stdout: string): Record<string, PullRequest> {
  const prs: Record<string, PullRequest> = {}
  const list = JSON.parse(stdout) as Array<{
    number: number
    state: PullRequest['state']
    isDraft: boolean
    headRefName: string
    url: string
    statusCheckRollup?: CheckRun[]
  }>
  for (const pr of list) {
    if (prs[pr.headRefName]) continue
    prs[pr.headRefName] = {
      number: pr.number,
      state: pr.state,
      isDraft: pr.isDraft,
      checks: rollup(pr.statusCheckRollup),
      url: pr.url,
    }
  }
  return prs
}

/** `gh run list --json headSha,status,conclusion`, newest first: each commit's latest run. */
export function parseRuns(stdout: string): Record<string, Checks> {
  const runs: Record<string, Checks> = {}
  const list = JSON.parse(stdout) as Array<{ headSha: string; status: string; conclusion: string }>
  for (const run of list) {
    if (runs[run.headSha]) continue
    runs[run.headSha] =
      run.status !== 'completed'
        ? 'pending'
        : ['success', 'skipped', 'neutral'].includes(run.conclusion)
          ? 'pass'
          : 'fail'
  }
  return runs
}

/** A search box entry read as git would narrow on it: a commit, a path, or text. */
export function readSearch(q: string): Search {
  const text = q.trim()
  if (text.startsWith('path:')) return { q: text.slice(5).trim(), mode: 'path' }
  if (/^[0-9a-f]{7,40}$/i.test(text)) return { q: text, mode: 'hash' }
  if (/[\\/]/.test(text) || /^[\w.-]+\.[a-z0-9]{1,5}$/i.test(text)) return { q: text, mode: 'path' }
  return { q: text, mode: 'text' }
}

/** The rows a live filter keeps: message, author, hash or ref name. */
export function filterRows(rows: readonly GraphRow[], query: string): GraphRow[] {
  const q = query.trim().toLowerCase()
  if (!q) return rows.slice()
  return rows.filter(
    row =>
      row.subject.toLowerCase().includes(q) ||
      row.author.toLowerCase().includes(q) ||
      row.hash.startsWith(q) ||
      row.refs.some(ref => ref.name.toLowerCase().includes(q)),
  )
}

/** The git arguments a scope selects. */
export function scopeRange(scope: string): string[] {
  if (scope === 'current') return ['HEAD']
  if (scope === 'local') return ['--branches', '--tags', 'HEAD']
  if (scope.startsWith('branch:')) return [scope.slice(7)]
  return ['--exclude=refs/stash', '--all']
}

/** One badge on a commit row: a local branch absorbs its `origin/` twin. */
export type Pill = { label: string; kind: RefKind; branch?: string; isSynced: boolean }

/** Folds each local branch with the remote branch of the same name on the same commit. */
export function pills(refs: readonly Ref[]): Pill[] {
  const locals = new Set(refs.filter(r => r.kind === 'head' || r.kind === 'branch').map(r => r.name))
  const absorbed = new Set<string>()
  const out: Pill[] = []
  for (const ref of refs) {
    if (ref.kind === 'head' || ref.kind === 'branch') {
      const twin = refs.find(r => r.kind === 'remote' && r.name.slice(r.name.indexOf('/') + 1) === ref.name)
      if (twin) absorbed.add(twin.name)
      out.push({ label: ref.name, kind: ref.kind, branch: ref.name, isSynced: Boolean(twin) })
    }
  }
  for (const ref of refs) {
    if (ref.kind === 'remote' && !absorbed.has(ref.name)) {
      const branch = ref.name.slice(ref.name.indexOf('/') + 1)
      out.push({ label: ref.name, kind: 'remote', branch: locals.has(branch) ? undefined : branch, isSynced: false })
    }
  }
  for (const ref of refs) {
    if (ref.kind === 'tag') out.push({ label: ref.name, kind: 'tag', isSynced: false })
  }
  return out
}

/** A merge message cut to what it says: `Merge #40 ← feat/pdf`, `Merge main → fix/x`. */
export function shortSubject(subject: string): string {
  const pr = subject.match(/^Merge pull request #(\d+) from [^/\s]+\/(\S+)/)
  if (pr) return `Merge #${pr[1]} ← ${pr[2]}`
  const branch = subject.match(/^Merge branch '([^']+)'(?: of \S+)?(?: into (\S+))?/)
  if (branch) return branch[2] ? `Merge ${branch[1]} → ${branch[2]}` : `Merge ${branch[1]}`
  const remote = subject.match(/^Merge remote-tracking branch '([^']+)'(?: into (\S+))?/)
  if (remote) return remote[2] ? `Merge ${remote[1]} → ${remote[2]}` : `Merge ${remote[1]}`
  return subject
}

/** `now`, `5m`, `2h`, `3d`, `5w`, `4mo`, `2y`. */
export function shortAgo(seconds: number, now: number): string {
  const s = Math.max(0, Math.round(now / 1000 - seconds))
  if (s < 60) return 'now'
  if (s < 3600) return `${Math.round(s / 60)}m`
  if (s < 86400) return `${Math.round(s / 3600)}h`
  if (s < 86400 * 14) return `${Math.round(s / 86400)}d`
  if (s < 86400 * 60) return `${Math.round(s / (86400 * 7))}w`
  if (s < 86400 * 365) return `${Math.round(s / (86400 * 30))}mo`
  return `${Math.round(s / (86400 * 365))}y`
}

/** `Haiouani Anis` → `Haiouani A.`; one word stays whole. */
export function shortAuthor(name: string): string {
  const words = name.trim().split(/\s+/)
  if (words.length < 2) return clip(name, 14)
  return clip(`${words[0]} ${words[words.length - 1]?.[0] ?? ''}.`, 14)
}

