import type { ClientModule, ClientPointerEvent } from 'claude-code'

/** What the grip draws: which way a drag resizes the pane. */
export type GripProps = { axis: 'x' | 'y' }

type Drag = { x0: number; y0: number; dx: number; dy: number } | null

/**
 * A drag handle drawn inside the pane: press, drag, release. On release it
 * posts the distance moved, in cells, and the hooks module resizes the pane.
 */
const Grip: ClientModule<GripProps, { drag: Drag; hover: boolean; isWired: boolean }> = (props, surface) => {
  const { Box, Text } = surface.elements
  const state = surface.state ?? { drag: null, hover: false, isWired: false }

  if (!state.isWired) {
    surface.onPointer((e: ClientPointerEvent) => {
      const now = surface.state ?? state
      if (e.type === 'enter' || e.type === 'leave') {
        surface.setState({ ...now, hover: e.type === 'enter' })
      } else if (e.type === 'down' && e.button === 'left') {
        surface.setState({ ...now, drag: { x0: e.x, y0: e.y, dx: 0, dy: 0 } })
      } else if (e.type === 'move' && now.drag) {
        surface.setState({ ...now, drag: { ...now.drag, dx: e.x - now.drag.x0, dy: e.y - now.drag.y0 } })
      } else if (e.type === 'up' && now.drag) {
        const { dx, dy } = now.drag
        surface.setState({ ...now, drag: null })
        if (dx !== 0 || dy !== 0) surface.post({ dx, dy })
      }
    })
    surface.setState({ ...state, isWired: true })
  }

  const delta = props.axis === 'x' ? state.drag?.dx : state.drag?.dy
  const label = state.drag
    ? props.axis === 'x'
      ? `⇔ ${delta && delta < 0 ? '+' : delta && delta > 0 ? '−' : ''}${Math.abs(delta ?? 0)} col`
      : `⇕ ${delta && delta > 0 ? '+' : delta && delta < 0 ? '−' : ''}${Math.abs(delta ?? 0)} rows`
    : props.axis === 'x'
      ? '⇔ drag'
      : '⇕ drag'

  return (
    <Box>
      <Text color={state.drag || state.hover ? 'suggestion' : '#A9B1BD'}>
        {label}
      </Text>
    </Box>
  )
}

export default Grip

