export type RefKind = 'head' | 'branch' | 'remote' | 'tag'

export type Ref = { name: string; kind: RefKind }

/** One stroke of a row's slice of the graph: lanes x1 to x2, rows 0 top, 1 middle, 2 bottom. */
export type Seg = { x1: number; y1: 0 | 1 | 2; x2: number; y2: 0 | 1 | 2; color: number }

export type GraphRow = {
  hash: string
  short: string
  subject: string
  author: string
  time: number
  refs: Ref[]
  lane: number
  color: number
  isMerge: boolean
  segs: Seg[]
}

/** A local branch against its upstream: `git for-each-ref %(upstream:track)`. */
export type Track = { upstream: string; ahead: number; behind: number; isGone: boolean }

export type WorkFile = { path: string; code: string }

/** The working tree: `git status --porcelain=v2 --branch`. */
export type WorkTree = {
  branch: string
  ahead: number
  behind: number
  staged: number
  modified: number
  untracked: number
  conflicted: number
  files: WorkFile[]
}

export type Stash = { hash: string; ref: string; subject: string; time: number }

export type Checks = 'pass' | 'fail' | 'pending' | 'none'

export type PullRequest = {
  number: number
  state: 'OPEN' | 'MERGED' | 'CLOSED'
  isDraft: boolean
  checks: Checks
  url: string
}

export type GitHub = {
  /** Pull requests by head branch name, the newest first. */
  prs: Record<string, PullRequest>
  /** The newest workflow run's outcome, by commit hash. */
  runs: Record<string, Checks>
  fetchedAt: number
  error?: string
}

/** How the log is narrowed on the git side: a message/author text, a path, or a commit. */
export type Search = { q: string; mode: 'text' | 'path' | 'hash' }

export type Graph = {
  repo: string
  total: number
  rows: GraphRow[]
  width: number
  head: string | null
  tracks: Record<string, Track>
  branches: string[]
  tags: string[]
  work: WorkTree | null
  stashes: Stash[]
  error?: string
}

export type FileStat = { path: string; added: number; deleted: number }

export type Detail = {
  kind: 'commit' | 'compare' | 'worktree'
  hash: string
  short: string
  /** The compare's other end, `base..hash`. */
  base?: string
  author: string
  email: string
  time: number
  subject: string
  body: string
  parents: string[]
  files: FileStat[]
}

export type FileDiff = { path: string; hunks: string }

/** `all`, `current`, `local`, or `branch:<name>`. */
export type Scope = string

/** Which name a git action in the details card is asking for. */
export type Naming = 'branch' | 'tag' | null

declare module 'claude-code' {
  interface PluginState {
    'git-graph': {
      graph: Graph | null
      selected: string | null
      detail: Detail | null
      diff: FileDiff[] | null
      limit: number
      scope: Scope
      query: string
      search: Search | null
      compareBase: string | null
      claude: string[]
      github: GitHub | null
      isStashOpen: boolean
      naming: Naming
      offset: number
      isHelpOpen: boolean
      isMoreOpen: boolean
    }
  }
}
